// Some portions generated by Codex
package org.eclipse.rdf4j.query.impl;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.StoredBNodeIdResolver;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.junit.jupiter.api.Test;

class BNodeOriginsTest {
	private static class Factory extends SimpleValueFactory implements StoredBNodeIdResolver {
		private int lookups;
		private boolean fail;

		@Override
		public boolean hasStoredBNodeId(String id) {
			lookups++;
			if (fail) {
				throw new IllegalStateException("lookup unavailable");
			}
			return true;
		}
	}

	@Test
	void generatedAndRemoteWrappersDoNotAcquireAuthorityFromEqualStoredIds() {
		var factory = new Factory();
		var origins = new BNodeOrigins(factory);
		BNode generated = new BlankNodeAllocationScope("issued-", ignored -> false).createBNode(factory);
		BNode equalStored = factory.createBNode(generated.getID());
		assertThat(origins.isReference(equalStored)).isTrue();
		assertThat(origins.isReference(generated)).isFalse();
		Object epoch = new Object();
		BNode remote = (BNode) RemoteBNode.newResponseScope(
				new BlankNodeAllocationScope("alias-", ignored -> false), factory, epoch, true)
				.map(factory.createBNode("canonical-remote"));
		assertThat(origins.isReference(factory.createBNode(remote.getID()))).isTrue();
		assertThat(origins.isReference(remote)).isFalse();
		assertThat(factory.lookups).isEqualTo(2);
	}

	@Test
	void lookupFailurePropagatesAndRepeatedStoredLookupsAreCached() {
		var factory = new Factory();
		var origins = new BNodeOrigins(factory);
		var node = factory.createBNode("stored");
		assertThat(origins.isReference(node)).isTrue();
		assertThat(origins.isReference(factory.createBNode("stored"))).isTrue();
		assertThat(factory.lookups).isEqualTo(1);
		factory.fail = true;
		assertThatThrownBy(() -> origins.isReference(factory.createBNode("other")))
				.isInstanceOf(IllegalStateException.class)
				.hasMessage("lookup unavailable");
	}

	@Test
	void theLookupCacheIsBoundedSoAStreamedResultDoesNotRetainEveryBlankNodeId() {
		var factory = new Factory();
		var origins = new BNodeOrigins(factory);
		// The most recent lookups a result keeps: enough for any page of results, bounded for a streamed export.
		int bound = 65_536;
		assertThat(origins.isReference(factory.createBNode("first"))).isTrue();
		for (int index = 0; index < bound; index++) {
			origins.isReference(factory.createBNode("node-" + index));
		}
		assertThat(factory.lookups).isEqualTo(bound + 1);
		// The oldest entry left the cache: asking for it again asks the store again.
		assertThat(origins.isReference(factory.createBNode("first"))).isTrue();
		assertThat(factory.lookups).isEqualTo(bound + 2);
		// A recently asked node is still cached.
		assertThat(origins.isReference(factory.createBNode("node-" + (bound - 1)))).isTrue();
		assertThat(factory.lookups).isEqualTo(bound + 2);
	}

	@Test
	void queryGeneratedAndNegotiatedProvenanceSurvivesTrustedCopiesAndPrivateSpills() throws Exception {
		var factory = SimpleValueFactory.getInstance();
		BNode generated = new BlankNodeAllocationScope("issued-", ignored -> false).createBNode(factory);
		var stored = RepositoryBNode.fromNegotiatedResult("encoded-stored", "raw-stored", true);
		Value original = factory.createTripleTerm(generated, factory.createIRI("urn:p"),
				factory.createTripleTerm(stored, factory.createIRI("urn:q"), generated));
		Value copy = factory.createTripleTerm(factory.createBNode(generated.getID()), factory.createIRI("urn:p"),
				factory.createTripleTerm(factory.createBNode(stored.getID()), factory.createIRI("urn:q"),
						factory.createBNode(generated.getID())));
		var preserved = RemoteBNode.preserveProvenance(original, copy);
		assertThat(preserved).isEqualTo(original);
		try (var spill = new RemoteBNode.SpillScope()) {
			RepositoryBNode restored = (RepositoryBNode) spill.resolve(spill.replace(stored));
			assertThat(restored).isEqualTo(stored);
			assertThat(restored.getRawID()).isEqualTo(stored.getRawID());
			assertThat(restored.isReference()).isTrue();
		}
		byte[] serialized;
		try (var bytes = new ByteArrayOutputStream(); var output = new ObjectOutputStream(bytes)) {
			output.writeObject(stored);
			output.flush();
			serialized = bytes.toByteArray();
		}
		try (var input = new ObjectInputStream(new ByteArrayInputStream(serialized))) {
			assertThat(((RepositoryBNode) input.readObject()).isReference()).isFalse();
		}
		assertThat(new BNodeOrigins(new Factory()).isReference(generated)).isFalse();
	}
}
